/// <summary>
/// Extension class for SourceDocumentStateInProcessVendInvoice to send purchase order invoiced business event.
/// </summary>
[ExtensionOf(classStr(SourceDocumentStateInProcessVendInvoice))]
final class METSourceDocumentStateInProcessVendInvoice_Extension
{
}

Method.Source:
/// <summary>
/// Task 305538: PB033 -CB492 - PO status 'Invoiced is not appearing in Abbyy Open PO table (Bug - 290169) - D365 Build
/// </summary>
/// <returns>BusinessEventsBase</returns>
protected BusinessEventsBase getBusinessEvent()
{
    VendorInvoicePostedBusinessEvent        metBusinessEvent;
    METPurchaseOrderInvoicedBusinessEvent   metPOInvoicedBusinessEvent;

    if (targetSourceDocumentAccountingStatus == SourceDocumentAccountingStatus::Completed)
    {
        PurchTable          purchTable;
        VendInvoiceJour     vendInvoiceJour = VendInvoiceJour::findSourceDocumentHeader(sourceDocumentHeader.RecId);

        purchTable = PurchTable::find(vendInvoiceJour.PurchId);

        if (purchTable && vendInvoiceJour)
        {
            if (BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(METPurchaseOrderInvoicedBusinessEvent)))
            {
                metPOInvoicedBusinessEvent = METPurchaseOrderInvoicedBusinessEvent::construct(vendInvoiceJour, purchTable);
                metPOInvoicedBusinessEvent.send();
            }
        }
    }

    metBusinessEvent = next getBusinessEvent();

    return metBusinessEvent;
}
